/*
 * Stand-in for kernel include/dt-bindings/input/input-event-codes.h.
 * Values are the Linux input key codes used by the DEEPoS board DTS.
 */
#ifndef _DT_BINDINGS_INPUT_EVENT_CODES_H
#define _DT_BINDINGS_INPUT_EVENT_CODES_H

#define KEY_UP 103
#define KEY_LEFT 105
#define KEY_RIGHT 106
#define KEY_DOWN 108
#define KEY_VOLUMEDOWN 114
#define KEY_VOLUMEUP 115
#define KEY_FN 0x1d0

#define BTN_SOUTH 0x130
#define BTN_EAST 0x131
#define BTN_NORTH 0x133
#define BTN_WEST 0x134
#define BTN_TL 0x136
#define BTN_TR 0x137
#define BTN_TL2 0x138
#define BTN_TR2 0x139
#define BTN_SELECT 0x13a
#define BTN_START 0x13b
#define BTN_MODE 0x13c

#endif
